{
  "findings": [
    {
      "ref": "[D527]",
      "area": "contact",
      "claim": "A parent reports that live, unmoderated voice and text chat can expose children to random strangers and profanity.",
      "stance": "risk",
      "quote": "Live, unmoderated chat is possible between users in the console and PC versions of Fortnite: Battle Royale. Options include voice chat and on-screen text chat. This exposes players to random strangers and the likelihood of profanity."
    },
    {
      "ref": "[D527]",
      "area": "money",
      "claim": "The game encourages frequent purchases of new content through seasonal updates and Battle Passes.",
      "stance": "risk",
      "quote": "Seasons seem to update approximately every 10–12 weeks, and 10 seasons make up a chapter. You'll begin to see clues to the updates during the current season, usually to encourage players to purchase the next season's Battle Pass."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that the platform collects user data and may share it with third parties for advertising, though the text does not specify deletion options.",
      "stance": "neutral",
      "quote": "The text does not provide explicit details about data collection, tracking for ads, or deletion mechanisms; however, it mentions that the platform's live events attract millions of viewers, implying data use for promotional purposes."
    },
    {
      "ref": "[D527]",
      "area": "age_gating",
      "claim": "A parent reports that the game does not enforce a strict age gate, as children can access it across multiple platforms without clear age verification.",
      "stance": "risk",
      "quote": "Users need an internet connection to play. Players can play \"cross-platform,\" which means, for example, that a Windows player can be on a team with a console player. Gamers can also create an account on any device and carry over their progress in a game to another system."
    },
    {
      "ref": "[D527]",
      "area": "content",
      "claim": "A parent reports that live events, such as concerts and promotional launches, are family-friendly and widely advertised.",
      "stance": "neutral",
      "quote": "Some of these events are scheduled and some are spontaneous. If your kid's into Fortnite, they'll probably hear the buzz and want to tune in. Events tend to be family-friendly and are listed in the [news section of the Fortnite site](https://www.epicgames.com/fortnite/en-US/news)."
    },
    {
      "ref": "[D527]",
      "area": "developer_record",
      "claim": "A parent reports no known fines, breaches, lawsuits, or regulatory actions against the developer are mentioned in the text.",
      "stance": "neutral",
      "quote": "The text does not mention any fines, breaches, lawsuits, or regulatory actions involving the developer."
    }
  ]
}
